import {chooseLibrary,createLibrary,rememberedLibrary,requireLibrary,folderCatalog,readLibraryFile,downloadText} from './sector-folder.js';
import {expandPlaceholder} from './sector-placeholder.js';
const $=id=>document.getElementById(id);let entries=[],folderMode=false;
function render(){const query=$('search').value.toLowerCase(),shown=entries.filter(e=>(!$('role').value||e.role===$('role').value)&&(!$('feature').value||(e.config.feature?.kind||'land')===$('feature').value)&&(!$('progress').value||e.status===$('progress').value)&&e.id.includes(query));$('status').textContent=`${shown.length} of ${entries.length} configurations · ${entries.reduce((n,e)=>n+(e.variants||[]).filter(v=>v!=='placeholder.json').length,0)} saved map variants`;$('cards').replaceChildren();for(const e of shown){const article=document.createElement('article'),img=document.createElement('img');if(!folderMode)img.src=`sector-library/${e.id}/${/^[a-zA-Z0-9_-]+\.svg$/.test(e.preview||'')?e.preview:'preview.svg'}`;img.alt=e.id;img.loading='lazy';const name=document.createElement('h2');name.textContent=e.id;const badge=document.createElement('small');badge.className='badge';badge.textContent=e.status;const detail=document.createElement('small');detail.textContent=`${(e.variants||[]).filter(v=>v!=='placeholder.json').length} saved maps · ${e.difficulties.join(' / ')} · ${e.equivalents?.length||4} orientations`;const select=document.createElement('select');select.setAttribute('aria-label','Orientation for '+e.id);for(const [i,t]of e.allowedTransforms.entries()){const o=document.createElement('option');o.value=i;o.textContent=(t.mirror?'Mirror + ':'')+t.turns*90+'°';select.append(o);}const variants=document.createElement('select');variants.setAttribute('aria-label','Variant for '+e.id);for(const name of e.variants||['placeholder.json']){if(!/^[a-zA-Z0-9_-]+\.json$/.test(name))continue;const o=document.createElement('option');o.value=name;o.textContent=name;variants.append(o);}const open=document.createElement('a');open.textContent='Open in 3D editor';const update=()=>{const authored=variants.value!=='placeholder.json',meta=e.variantDetails?.[variants.value];badge.textContent=authored?(meta?.status==='authored'?'Ready for review':'In progress'):'Untouched placeholder';const preview=meta?.preview||(authored?e.preview:'preview.svg');img.src=`sector-library/${e.id}/${/^[a-zA-Z0-9_-]+\.svg$/.test(preview||'')?preview:'preview.svg'}`;if(folderMode){const chosen=preview||'preview.svg',selectedVariant=variants.value;readLibraryFile(e.id,chosen,e.collectionRole).then(svg=>{if(variants.value!==selectedVariant)return;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}).catch(()=>{img.removeAttribute('src');img.alt='Preview unavailable';});}select.disabled=authored;if(authored)select.value='0';open.href=`editor-3d.html?editing=1&${folderMode?"library=folder&":""}sectorTemplate=${encodeURIComponent(e.id)}&orientation=${select.value}&variant=${encodeURIComponent(variants.value)}`;};select.onchange=variants.onchange=update;update();const download=document.createElement('button');download.textContent='Export full map';download.onclick=async()=>{if(variants.value!=='placeholder.json'){if(folderMode)downloadText(await readLibraryFile(e.id,variants.value,e.collectionRole),variants.value);else window.open(`sector-library/${e.id}/${variants.value}`,'_blank','noopener');return;}const map=expandPlaceholder(e,e.allowedTransforms[+select.value]),url=URL.createObjectURL(new Blob([JSON.stringify(map)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=e.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};article.append(img,name,badge,detail,variants,select,open,download);$('cards').append(article);}}
for(const id of ['search','role','feature','progress'])$(id).addEventListener('input',render);
async function bundled(){folderMode=false;try{const response=await fetch('sector-library/index.json');if(!response.ok)throw Error('Index unavailable');const index=await response.json();entries=await Promise.all(index.entries.map(async e=>{const r=await fetch(`sector-library/${e.id}/placeholder.json`);if(!r.ok)throw Error('Missing '+e.id);return r.json();}));render();}catch(e){$('status').textContent='Library could not load: '+e.message;}
}
async function showFolder(){const root=await requireLibrary();entries=await folderCatalog(root);folderMode=true;$('folder-status').textContent='Selected folder: '+root.name+' · saves and reads use this folder';render();}
$('choose-library-folder').onclick=async()=>{try{await chooseLibrary();await showFolder();}catch(e){$('folder-status').textContent=e.message;}};
$('create-library-folder').onclick=async()=>{try{$('folder-status').textContent='Choose an empty folder named AnimalFactoryMaps. Copying starter maps may take a moment…';await createLibrary();await showFolder();}catch(e){$('folder-status').textContent=e.message;}};
$('bundled-library').onclick=()=>{$('folder-status').textContent='Showing bundled maps.';bundled();};
try{if(await rememberedLibrary())await showFolder();else await bundled();}catch(e){$('folder-status').textContent=e.message;await bundled();}
